BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (379::BIGINT, 'Muy buen profesor y trata sobretodo que el estudiante entienda la materia, los examenes son cortos y sencillos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '3d82c7fb575f3e5e39c3cbf91633fa8fe48ade454cb6717544eb9ee970835452'::TEXT, ARRAY[1276]::BIGINT[]),
    (379::BIGINT, 'Es un profesor que siempre está dispuesto a ayudar. Explica bien, aunque se pone nervioso si lo refutan. Exámenes sencillos. Da muchos puntos extra por trabajos sumamente sencillos. Se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'd4fcd4f76c18c44b6a230a2e6c6ac188fc4d106491826671515eeaed204ee5f9'::TEXT, ARRAY[1307]::BIGINT[]),
    (379::BIGINT, 'Hayden es un amor de profe. Los exámenes son fáciles, el resto de evaluaciones son un regalo y deja trabajos de puntos extra. Hay que esforzarse para quedarse. Tal vez no sea tan claro explicando, pero si usted le pregunta, él va a hacer todo lo posible para que usted entienda. Una teja de persona.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'ebfb436721b9af83ad5d2e01f824d9eb5ff7ea9cecb81fa463b7327a2389948a'::TEXT, ARRAY[1307]::BIGINT[]),
    (379::BIGINT, 'tiene un buen dominio de la materia, consigase exámenes viejos y pasa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '8e3d04c9f9ddd88d7a26fafcf818c124b7a137cb01e8fa51de7e9894a64e90af'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Excelente profesor, clases claras, super buena nota, califica justo y si se enreda un poco rápido se vuelve a ordenar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'f1feadabcc0276952b6f0499f66377fa638d1a0442c6049ac68f235c1acb4b25'::TEXT, ARRAY[1267, 1363]::BIGINT[]),
    (379::BIGINT, 'Una belleza de persona! Se nota su entusiasmo por enseñar y lo hace bien! No se anda con rodeos, enseña lo que hay que saber y deja tareas extra opcionales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-20T00:00:00+00:00'::TIMESTAMPTZ, '9972821452187e09775f5ebe6d8c8b1a2c207c8fe05b4eef27182bc237a1db8a'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Excelente profe, explica detalladamente y siempre da sus clases con mucho ánimo. Recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'defa43a46890504c9d3124aca2651ddf3c86b9433ad847b150398961907f6005'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Es un amor de profe, su clases son un toque monótonas y aburridas, pero es imposible que le vaya mal llevándolo con Hayden, y lo mejor es que uno termina entendiendo bastante bien cómo funcionan las cosas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '331731fb6e168a8983d52d656316104c5d188e93aa0826b81aa9358e9be54363'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Es el mejor profe, hace el curso súper fácil. Le encanta lo que enseña, es imposible salir mal. Exámenes muy fáciles. El mejor de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '56b48ebd8583982aaaa95d51640bb65fca5f9fea2c9ba9b89d5e62df32653122'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Un excelente profe, no entiendo por qué no hay más profes de Electrónica como él 100 % recomendado califica justo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '81c55a14b92f1461f0893f670a7ee27b8cb5e41f37981d3885c3363cd9fb4dc5'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Es excelente. No hace evaluaciones nada difíciles, explica mil veces si no se entiende y se preocupa mucho por el estudiante. Es muy humilde. Sus puntos bajos son la forma de calificar y la monotonía de sus lecciones, pero no es malintencionado en absoluto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '10bf0165faf4607b41ac23f52009dd71a1f077156aa9a2e669182f1a1b6b8d84'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Excelente profesor trata de explicar de mejor manera la materia, ayuda mucho cuando alguien no entiende y no hace examenes rudos. De los mejores de la escuela de electronica'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'fc72cfaad9d4b236bd6ec849367588d3969b4db653d43f6b345acbc4b591db2c'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Excelente persona, muy humilde, explica cuantas veces sea necesario y con buen modo. A veces se confunde cuando está dando la teoría, pero eventualmente se corrige. Ayuda infinita, sacrifica tiempo extra para ayudar con dudas o proyectos. Recicla exámenes y califica normal.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-17T00:00:00+00:00'::TIMESTAMPTZ, '72491d4ce5854ee552c6340b962017ac627069bda96c7c13a328d099e92396e1'::TEXT, ARRAY[1267, 1321]::BIGINT[]),
    (379::BIGINT, 'La clase es monótona pero él explica todo lo que hace falta cuantes veces sea necesario. Ayuda en todo lo posible y el mínimo esfuerzo en estudiar da una buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, '673166d8aa903a2a9cd421118b2cb6945ed3546d795a184031c8c8448a080301'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Muy buen profe, da toda la materia del curso sin volverlo un curso pesado. Las evaluaciones son faciles pero califica un poco rudo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'c2c93d866131ada64014d1107273b3618553bffdc4477cab1b00b56abe34038b'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Este profesor para mi gusto no sirve para dar esta materia puesto que la teoría es muy larga (la da con diapositivas) y no hace ejercicios. Sin embargo lo único que tiene que hacer usted para pasar el curso es hacer exámenes viejos, debido a que sus exámenes van a ser un 99% parecidos. Da 6% extra'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Da crédito extra']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'e82abc97a6ea2e8a14d9a701876ec06da70b38565cfcdec7be9daf74f84a275c'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Es un profe muy buena gente, a veces se enreda pero si uno le pregunta trata de dejar todo muy claro, hace quices de puntos extra para ayudar a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Muchos exámenes']::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a21b195741ab1b839c6a272ea36e737573d66e4783d7abc821edec119a2497c6'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Es bueno. Considera que uno es estudiante y lleva otros cursos. Hace quices extra demasiado fáciles que ayudan un montón al final. No es el mejor explicando pero si uno le pregunta el hará todo lo posible por aclararlo. También es muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'dbdab842612b5d3ad022ab348f681e1ad5602ee38f8e62989c26f3b9eef33c7e'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Sin duda el mejor que ha dado el curso, explica demasiado bien cada uno de los temas y de forma detallada, ademas hace muchos ejemplos. Los quices son un regalo pero si califica rudo los examenes (como todos). Se aprende de verdad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c002c8bade0782a9525fd2dfeea1dcb2ceee91e2c14b4d4db403ebc179418876'::TEXT, ARRAY[1257]::BIGINT[]),
    (379::BIGINT, 'ES UN PROFE REGULAR.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e81daa5afafe02cd76cc020f3920ac685e87e649beae2380116d8115e2b45b34'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'Le falta experiencia y debido a esto suele enredarse y explicar no tan bien, sin embargo tambien hay dias que explica muy bien! Es de esos profes pura vida y que se interesa en que la gente entienda y aprenda. Cuando lo lleve hizo quices de puntos extra que eran faciles!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '62866d059ff863f223f3764a1207dd83c2658f19531daf3b95aabb583750b6a7'::TEXT, ARRAY[1267]::BIGINT[]),
    (379::BIGINT, 'CC es un curso difícil pero este profesor es demasiado bueno, explica excelente y en detalle cada uno de los temas, hace muchos ejemplos, repasos todas las clases del tema anterior, quices muy sencillos y califica justo! No es binario!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3a9e3bf6d4c72e562e5a6ad1096cba330b8ceaf73ffeb3d41a0aa88090c440d2'::TEXT, ARRAY[1257]::BIGINT[]),
    (379::BIGINT, 'Es nuevo, así que la falta de experiencia al enseñar se nota pero trata de hacerlo lo más claro posible. las lecciones antes de un exámen hace práctica de problemas, con solo eso es casi imposible perder los del exámen pues son casi (sino) los mismos. Eso sí, califica duro, pero es pasable'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '21666f2160c8451befd3f7dfba8f7636821736afc8fb69c28e33278e93b42332'::TEXT, ARRAY[1267]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
